template <class T, qsizetype Prealloc>
inline QVarLengthArray<T, Prealloc>::QVarLengthArray(qsizetype asize)
    : QVarLengthArray()
{
    static_cast<void>(false && (asize >= 0))
                                                          ;




    if (asize > Prealloc) {
        this->ptr = malloc(asize * sizeof(T));
        do { if (!(this->ptr)) qBadAlloc(); } while (false);
        this->a = asize;
    }
    if constexpr (QTypeInfo<T>::isComplex)
        std::uninitialized_default_construct_n(data(), asize);
    this->s = asize;
}

template <class T>
template <typename AT>
inline qsizetype QVLABase<T>::indexOf(const AT &t, qsizetype from) const
{
    if (from < 0)
        from = qMax(from + size(), qsizetype(0));
    if (from < size()) {
        const T *n = data() + from - 1;
        const T *e = end();
        while (++n != e)
            if (*n == t)
                return n - data();
    }
    return -1;
}

template <class T>
template <typename AT>
inline qsizetype QVLABase<T>::lastIndexOf(const AT &t, qsizetype from) const
{
    if (from < 0)
        from += size();
    else if (from >= size())
        from = size() - 1;
    if (from >= 0) {
        const T *b = begin();
        const T *n = b + from + 1;
        while (n != b) {
            if (*--n == t)
                return n - b;
        }
    }
    return -1;
}

template <class T>
template <typename AT>
inline bool QVLABase<T>::contains(const AT &t) const
{
    const T *b = begin();
    const T *i = end();
    while (i != b) {
        if (*--i == t)
            return true;
    }
    return false;
}

template <class T>
 void QVLABase<T>::append_impl(qsizetype prealloc, void *array, const T *abuf, qsizetype increment)
{
    static_cast<void>(false && (abuf || increment == 0));
    if (increment <= 0)
        return;

    const qsizetype asize = size() + increment;

    if (asize >= capacity())
        growBy(prealloc, array, increment);

    if constexpr (QTypeInfo<T>::isComplex)
        std::uninitialized_copy_n(abuf, increment, end());
    else
        memcpy(static_cast<void *>(end()), static_cast<const void *>(abuf), increment * sizeof(T));

    this->s = asize;
}

template <class T>
 void QVLABase<T>::assign_impl(qsizetype prealloc, void *array, qsizetype n, const T &t)
{
    static_cast<void>(false && (n >= 0));
    if (n > capacity()) {
        reallocate_impl(prealloc, array, 0, capacity());
        resize_impl(prealloc, array, n, t);
    } else {
        auto mid = (std::min)(n, size());
        std::fill(data(), data() + mid, t);
        std::uninitialized_fill(data() + mid, data() + n, t);
        s = n;
        erase(data() + n, data() + size());
    }
}

template <class T>
template <typename Iterator>
 void QVLABase<T>::assign_impl(qsizetype prealloc, void *array, Iterator first, Iterator last)
{

    constexpr bool IsFwdIt =
            std::is_convertible_v<typename std::iterator_traits<Iterator>::iterator_category,
                                  std::forward_iterator_tag>;
    if constexpr (IsFwdIt) {
        const qsizetype n = std::distance(first, last);
        if (n > capacity())
            reallocate_impl(prealloc, array, 0, n);
    }

    auto dst = begin();
    const auto dend = end();
    while (true) {
        if (first == last) {
            std::destroy(dst, dend);
            break;
        }
        if (dst == dend) {
            if constexpr (IsFwdIt) {
                dst = std::uninitialized_copy(first, last, dst);
                break;
            } else {
                do {
                    emplace_back_impl(prealloc, array, *first);
                } while (++first != last);
                return;
            }
        }
        *dst = *first;
        ++dst;
        ++first;
    }
    this->s = dst - begin();
}

template <class T>
 void QVLABase<T>::reallocate_impl(qsizetype prealloc, void *array, qsizetype asize, qsizetype aalloc)
{
    static_cast<void>(false && (aalloc >= asize));
    static_cast<void>(false && (data()));
    T *oldPtr = data();
    qsizetype osize = size();

    const qsizetype copySize = qMin(asize, osize);
    static_cast<void>(false && (copySize >= 0));

    if (aalloc != capacity()) {
        QVLABaseBase::malloced_ptr guard;
        void *newPtr;
        qsizetype newA;
        if (aalloc > prealloc) {
            newPtr = malloc(aalloc * sizeof(T));
            guard.reset(newPtr);
            do { if (!(newPtr)) qBadAlloc(); } while (false);

            newA = aalloc;
        } else {
            newPtr = array;
            newA = prealloc;
        }
        QtPrivate::q_uninitialized_relocate_n(oldPtr, copySize,
                                              reinterpret_cast<T *>(newPtr));

        ptr = newPtr;
        guard.release();
        a = newA;
    }
    s = copySize;


    if constexpr (QTypeInfo<T>::isComplex) {
        if (osize > asize)
            std::destroy(oldPtr + asize, oldPtr + osize);
    }

    if (oldPtr != reinterpret_cast<T *>(array) && oldPtr != data())
        free(oldPtr);
}

template <class T>
 T QVLABase<T>::value(qsizetype i) const
{
    if (size_t(i) >= size_t(size()))
        return T();
    return operator[](i);
}
template <class T>
 T QVLABase<T>::value(qsizetype i, const T &defaultValue) const
{
    return (size_t(i) >= size_t(size())) ? defaultValue : operator[](i);
}

