template <class T>
template <typename...Args>
 auto QVLABase<T>::emplace_impl(qsizetype prealloc, void *array, const_iterator before, Args &&...args) -> iterator
{
    static_cast<void>(false && (isValidIterator(before)));
    static_cast<void>(false && (size() <= capacity()));
    static_cast<void>(false && (capacity() > 0));

    const qsizetype offset = qsizetype(before - cbegin());
    emplace_back_impl(prealloc, array, std::forward<Args>(args)...);
    const auto b = begin() + offset;
    const auto e = end();
    QtPrivate::q_rotate(b, e - 1, e);
    return b;
}

template <class T>
 auto QVLABase<T>::insert_impl(qsizetype prealloc, void *array, const_iterator before, qsizetype n, const T &t) -> iterator
{
    static_cast<void>(false && (isValidIterator(before)));

    const qsizetype offset = qsizetype(before - cbegin());
    resize_impl(prealloc, array, size() + n, t);
    const auto b = begin() + offset;
    const auto e = end();
    QtPrivate::q_rotate(b, e - n, e);
    return b;
}

template <class T>
 auto QVLABase<T>::erase(const_iterator abegin, const_iterator aend) -> iterator
{
    static_cast<void>(false && (isValidIterator(abegin)));
    static_cast<void>(false && (isValidIterator(aend)));

    qsizetype f = qsizetype(abegin - cbegin());
    qsizetype l = qsizetype(aend - cbegin());
    qsizetype n = l - f;

    if (n == 0)
        return data() + f;

    static_cast<void>(false && (n > 0));

    if constexpr (!QTypeInfo<T>::isRelocatable) {
        std::move(begin() + l, end(), (begin() + f));
        std::destroy(end() - n, end());
    } else {
        std::destroy(abegin, aend);
        memmove(static_cast<void *>(data() + f), static_cast<const void *>(data() + l), (size() - l) * sizeof(T));
    }
    this->s -= n;
    return data() + f;
}
