template <class T>
inline QDebugIfHasDebugStream<T> operator<<(QDebug debug, const std::optional<T> &opt)
{
    const QDebugStateSaver saver(debug);
    if (!opt)
        debug.nospace() << std::nullopt;
    else
        debug.nospace() << "std::optional(" << *opt << ')';
    return debug;
}

